SELECT 'iam_snapshot_guard_order',ABS(1-(SELECT COUNT(*) FROM information_schema.TRIGGERS a JOIN information_schema.TRIGGERS b ON a.TRIGGER_SCHEMA=b.TRIGGER_SCHEMA AND a.EVENT_OBJECT_TABLE=b.EVENT_OBJECT_TABLE AND b.TRIGGER_NAME='mt5d_event_insert' WHERE a.TRIGGER_SCHEMA=DATABASE() AND a.TRIGGER_NAME='mt5d_event_snapshot_shape' AND a.ACTION_TIMING='BEFORE' AND a.EVENT_MANIPULATION='INSERT' AND a.ACTION_ORDER=b.ACTION_ORDER+1));
SELECT 'iam_nonflat_snapshot',COUNT(*) FROM institution_membership_event WHERE JSON_TYPE(previous_roles)<>'ARRAY' OR JSON_TYPE(new_roles)<>'ARRAY' OR JSON_LENGTH(previous_roles)>3 OR JSON_LENGTH(new_roles)>3 OR (JSON_LENGTH(previous_roles)>0 AND JSON_TYPE(JSON_EXTRACT(previous_roles,'$[0]'))<>'STRING') OR (JSON_LENGTH(previous_roles)>1 AND JSON_TYPE(JSON_EXTRACT(previous_roles,'$[1]'))<>'STRING') OR (JSON_LENGTH(previous_roles)>2 AND JSON_TYPE(JSON_EXTRACT(previous_roles,'$[2]'))<>'STRING') OR (JSON_LENGTH(new_roles)>0 AND JSON_TYPE(JSON_EXTRACT(new_roles,'$[0]'))<>'STRING') OR (JSON_LENGTH(new_roles)>1 AND JSON_TYPE(JSON_EXTRACT(new_roles,'$[1]'))<>'STRING') OR (JSON_LENGTH(new_roles)>2 AND JSON_TYPE(JSON_EXTRACT(new_roles,'$[2]'))<>'STRING');
